import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark_df = inputs["watermark"]

    # Extract the high_ts watermark
    if len(watermark_df) == 0:
        high_ts = pd.Timestamp.min
    else:
        high_ts = watermark_df["high_ts"].iloc[0]

    # Filter events with event_ts > high_ts (new events since last load)
    new_events = cdc_events[cdc_events["event_ts"] > high_ts].copy()

    # Sort by user_id, then by (event_ts, event_seq) to process sequentially per user
    new_events = new_events.sort_values(by=["user_id", "event_ts", "event_seq"]).reset_index(drop=True)

    # Create a dictionary to track the current state of each user
    # Key: user_id, Value: {email, status, status_ts}
    state = {}

    # Initialize state from target_snapshot
    for _, row in target_snapshot.iterrows():
        user_id = row["user_id"]
        state[user_id] = {
            "email": row["email"],
            "status": row["status"],
            "status_ts": row["status_ts"]
        }

    # Process each event in order
    for _, event in new_events.iterrows():
        user_id = event["user_id"]
        event_ts = event["event_ts"]
        op = event["op"]
        email = event["email"]

        # Get current state or initialize if new user
        if user_id not in state:
            state[user_id] = {
                "email": None,
                "status": None,
                "status_ts": None
            }

        current = state[user_id]

        if op == "U":
            # Update operation
            if current["status"] == "DELETED":
                # Check if resurrection is allowed (strictly > 7 days)
                if current["status_ts"] is not None:
                    days_since_deletion = (event_ts - current["status_ts"]).total_seconds() / (86400)
                    if days_since_deletion > 7:
                        # Resurrection allowed
                        state[user_id] = {
                            "email": email,
                            "status": "ACTIVE",
                            "status_ts": event_ts
                        }
                    # else: discard the update (deletion is sticky)
                else:
                    # No status_ts, treat as new user
                    state[user_id] = {
                        "email": email,
                        "status": "ACTIVE",
                        "status_ts": event_ts
                    }
            else:
                # Update on ACTIVE or new user
                state[user_id] = {
                    "email": email,
                    "status": "ACTIVE",
                    "status_ts": event_ts
                }

        elif op == "D":
            # Soft delete operation
            state[user_id] = {
                "email": current["email"],  # Preserve email as of deletion
                "status": "DELETED",
                "status_ts": event_ts
            }

    # Convert state back to DataFrame
    result_rows = []
    for user_id, user_state in state.items():
        result_rows.append({
            "user_id": user_id,
            "email": user_state["email"],
            "status": user_state["status"],
            "status_ts": user_state["status_ts"]
        })

    new_snapshot = pd.DataFrame(result_rows)

    # Ensure correct dtypes
    if len(new_snapshot) > 0:
        new_snapshot["user_id"] = new_snapshot["user_id"].astype("int64")
        new_snapshot["email"] = new_snapshot["email"].astype("object")
        new_snapshot["status"] = new_snapshot["status"].astype("object")
        new_snapshot["status_ts"] = pd.to_datetime(new_snapshot["status_ts"], utc=False)
    else:
        new_snapshot["user_id"] = new_snapshot["user_id"].astype("int64")
        new_snapshot["email"] = new_snapshot["email"].astype("object")
        new_snapshot["status"] = new_snapshot["status"].astype("object")
        new_snapshot["status_ts"] = pd.to_datetime(new_snapshot["status_ts"], utc=False)

    return {"new_snapshot": new_snapshot}
